from typing import Any, Dict

class DocumentRequest:
    def __init__(self, document_path: str):
        self.document_path = document_path

class DocumentResponse:
    def __init__(self, result: Dict[str, Any]):
        self.result = result

class NormalizedExpense:
    def __init__(self, vendor: str, date: str, total: float, items: Dict[str, Any]):
        self.vendor = vendor
        self.date = date
        self.total = total
        self.items = items

from.document_models import NormalizedExpense

def normalize_expense(expense: NormalizedExpense):
    return {
        'vendor': expense.vendor,
        'date': expense.date,
        'total': expense.total,
        'items': expense.items
    }

from.document_models import NormalizedExpense

def validate_document_fields(expense: NormalizedExpense):
    if not expense.vendor or not expense.date or not expense.total:
        raise ValueError('Missing required fields')
    if expense.total <= 0:
        raise ValueError('Total must be greater than zero')

import re

def moderate_vendor_text(text: str):
    if re.search(r'\b(sensitive|confidential)\b', text, re.IGNORECASE):
        raise ValueError('Vendor text contains sensitive information')
